    16→import {BeaconBlockBody, SSZTypesFor, SignedBeaconBlock, deneb, fulu, ssz} from "@lodestar/types";
    17→import {kzg} from "./kzg.js";
    18→
    19→type VersionHash = Uint8Array;
    20→
    21→export function kzgCommitmentToVersionedHash(kzgCommitment: deneb.KZGCommitment): VersionHash {
    22→  const hash = sha256Digest(kzgCommitment);
    23→  // Equivalent to `VERSIONED_HASH_VERSION_KZG + hash(kzg_commitment)[1:]`
    24→  hash[0] = VERSIONED_HASH_VERSION_KZG;
    25→  return hash;
    26→}
    27→
    28→export function computeInclusionProof(
    29→  fork: ForkName,
    30→  body: BeaconBlockBody,
    31→  index: number
    32→): deneb.KzgCommitmentInclusionProof {
    33→  const bodyView = (ssz[fork].BeaconBlockBody as SSZTypesFor<ForkAll, "BeaconBlockBody">).toView(body);
    34→  const commitmentGindex = KZG_COMMITMENT_GINDEX0 + index;
    35→  return new Tree(bodyView.node).getSingleProof(BigInt(commitmentGindex));
    36→}
    37→
    38→/**
    39→ * SPEC FUNCTION get_blob_sidecars
    40→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/deneb/validator.md#sidecar
    41→ */
    42→export function getBlobSidecars(
    43→  config: ChainForkConfig,
    44→  signedBlock: SignedBeaconBlock,
    45→  blobs: deneb.Blobs,
    46→  proofs: deneb.KZGProofs
    47→): deneb.BlobSidecars {
