   208→      blockKzgCommitments.length === 0 ||
   209→      blockKzgCommitments.length !== kzgCommitments.length ||
   210→      blockKzgCommitments
   211→        .map((commitment, i) => byteArrayEquals(commitment, kzgCommitments[i]))
   212→        .filter((result) => result === false).length
