   288→
   289→/**
   290→ * SPEC FUNCTION
   291→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#verify_data_column_sidecar_kzg_proofs
   292→ */
   293→export async function verifyDataColumnSidecarKzgProofs(
   294→  commitments: Uint8Array[],
   295→  cellIndices: number[],
   296→  cells: Uint8Array[],
   297→  proofs: Uint8Array[]
   298→): Promise<void> {
   299→  let valid: boolean;
