   328→ */
   329→export function computeSubnetForDataColumnSidecar(
   330→  config: ChainConfig,
   331→  columnSidecar: fulu.DataColumnSidecar
   332→): SubnetID {
   333→  return columnSidecar.index % config.DATA_COLUMN_SIDECAR_SUBNET_COUNT;
