    55→        dataAvailabilityStatus,
    56→        // false because it's verified below with better error typing
    57→        verifyStateRoot: false,
    58→        // if block is trusted don't verify proposer or op signature
    59→        verifyProposer: !useBlsBatchVerify && !validSignatures && !validProposerSignature,
    60→        verifySignatures: !useBlsBatchVerify && !validSignatures,
    61→      },
    62→      {metrics, validatorMonitor}
    63→    );
