   180→
   181→export async function validateDataColumnsSidecars(
   182→  blockSlot: Slot,
   183→  blockRoot: Root,
   184→  blockKzgCommitments: deneb.BlobKzgCommitments,
   185→  dataColumnSidecars: fulu.DataColumnSidecars,
   186→  metrics: Metrics | null,
   187→  opts: {skipProofsCheck: boolean} = {skipProofsCheck: false}
   188→): Promise<void> {
   189→  // Skip verification if there are no data columns
   190→  if (dataColumnSidecars.length === 0) {
   191→    return;
   192→  }
   193→
   194→  const commitmentBytes: Uint8Array[] = [];
   195→  const cellIndices: number[] = [];
   196→  const cells: Uint8Array[] = [];
   197→  const proofBytes: Uint8Array[] = [];
   198→
   199→  for (let sidecarsIndex = 0; sidecarsIndex < dataColumnSidecars.length; sidecarsIndex++) {
   200→    const columnSidecar = dataColumnSidecars[sidecarsIndex];
   201→    const {index: columnIndex, column, kzgCommitments, kzgProofs} = columnSidecar;
   202→    const columnBlockHeader = columnSidecar.signedBlockHeader.message;
   203→    const columnBlockRoot = ssz.phase0.BeaconBlockHeader.hashTreeRoot(columnBlockHeader);
   204→    if (
   205→      columnBlockHeader.slot !== blockSlot ||
   206→      !byteArrayEquals(columnBlockRoot, blockRoot) ||
   207→      kzgCommitments.length === 0 ||
   208→      blockKzgCommitments.length === 0 ||
   209→      blockKzgCommitments.length !== kzgCommitments.length ||
   210→      blockKzgCommitments
   211→        .map((commitment, i) => byteArrayEquals(commitment, kzgCommitments[i]))
   212→        .filter((result) => result === false).length
   213→    ) {
   214→      throw new Error(
   215→        `Invalid data column sidecar slot=${columnBlockHeader.slot} columnBlockRoot=${toRootHex(columnBlockRoot)} columnIndex=${columnIndex} for the block blockRoot=${toRootHex(blockRoot)} slot=${blockSlot} sidecarsIndex=${sidecarsIndex} kzgCommitments=${kzgCommitments.length} blockKzgCommitments=${blockKzgCommitments.length}`
   216→      );
   217→    }
   218→
   219→    if (columnIndex >= NUMBER_OF_COLUMNS) {
   220→      throw new Error(
   221→        `Invalid data sidecar columnIndex=${columnIndex} in slot=${blockSlot} blockRoot=${toRootHex(blockRoot)} sidecarsIndex=${sidecarsIndex}`
   222→      );
   223→    }
   224→
   225→    if (column.length !== kzgCommitments.length || column.length !== kzgProofs.length) {
   226→      throw new Error(
   227→        `Invalid data sidecar array lengths for columnIndex=${columnIndex} in slot=${blockSlot} blockRoot=${toRootHex(blockRoot)}`
   228→      );
   229→    }
   230→
   231→    commitmentBytes.push(...kzgCommitments);
   232→    cellIndices.push(...Array.from({length: column.length}, () => columnIndex));
   233→    cells.push(...column);
   234→    proofBytes.push(...kzgProofs);
   235→  }
   236→
   237→  if (opts.skipProofsCheck) {
   238→    return;
   239→  }
   240→
   241→  let valid: boolean;
   242→  try {
   243→    const timer = metrics?.peerDas.kzgVerificationDataColumnBatchTime.startTimer();
   244→    valid = await kzg.asyncVerifyCellKzgProofBatch(commitmentBytes, cellIndices, cells, proofBytes);
   245→    timer?.();
   246→  } catch (err) {
   247→    (err as Error).message =
   248→      `Error in verifyCellKzgProofBatch for slot=${blockSlot} blockRoot=${toRootHex(blockRoot)} commitmentBytes=${commitmentBytes.length} cellIndices=${cellIndices.length} cells=${cells.length} proofBytes=${proofBytes.length}`;
   249→    throw err;
   250→  }
   251→
   252→  if (!valid) {
   253→    throw new Error(`Invalid data column sidecars in slot=${blockSlot} blockRoot=${toRootHex(blockRoot)}`);
   254→  }
   255→}
   256→
   257→/**
   258→ * SPEC FUNCTION
   259→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#verify_data_column_sidecar
   260→ */
   261→export function verifyDataColumnSidecar(dataColumnSidecar: fulu.DataColumnSidecar): void {
   262→  if (dataColumnSidecar.index >= NUMBER_OF_COLUMNS) {
   263→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   264→      code: DataColumnSidecarErrorCode.INVALID_INDEX,
   265→      columnIdx: dataColumnSidecar.index,
   266→    });
   267→  }
   268→
   269→  if (dataColumnSidecar.kzgCommitments.length === 0) {
   270→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   271→      code: DataColumnSidecarErrorCode.NO_COMMITMENTS,
   272→      columnIdx: dataColumnSidecar.index,
   273→    });
   274→  }
   275→
   276→  if (
   277→    dataColumnSidecar.column.length !== dataColumnSidecar.kzgCommitments.length ||
   278→    dataColumnSidecar.column.length !== dataColumnSidecar.kzgProofs.length
   279→  ) {
   280→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   281→      code: DataColumnSidecarErrorCode.MISMATCHED_LENGTHS,
   282→      columnLength: dataColumnSidecar.column.length,
   283→      commitmentsLength: dataColumnSidecar.kzgCommitments.length,
   284→      proofsLength: dataColumnSidecar.kzgProofs.length,
   285→    });
   286→  }
   287→}
   288→
   289→/**
   290→ * SPEC FUNCTION
   291→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#verify_data_column_sidecar_kzg_proofs
   292→ */
   293→export async function verifyDataColumnSidecarKzgProofs(
   294→  commitments: Uint8Array[],
   295→  cellIndices: number[],
   296→  cells: Uint8Array[],
   297→  proofs: Uint8Array[]
   298→): Promise<void> {
   299→  let valid: boolean;
   300→  try {
   301→    valid = await kzg.asyncVerifyCellKzgProofBatch(commitments, cellIndices, cells, proofs);
   302→  } catch (e) {
   303→    (e as Error).message = `Error on asyncVerifyCellKzgProofBatch: ${(e as Error).message}`;
   304→    throw e;
   305→  }
   306→  if (!valid) {
   307→    throw Error("Invalid verifyCellKzgProofBatch");
   308→  }
   309→}
   310→
   311→/**
   312→ * SPEC FUNCTION
   313→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#verify_data_column_sidecar_inclusion_proof
   314→ */
   315→export function verifyDataColumnSidecarInclusionProof(dataColumnSidecar: fulu.DataColumnSidecar): boolean {
   316→  return verifyMerkleBranch(
   317→    ssz.deneb.BlobKzgCommitments.hashTreeRoot(dataColumnSidecar.kzgCommitments),
   318→    dataColumnSidecar.kzgCommitmentsInclusionProof,
   319→    KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH,
   320→    KZG_COMMITMENTS_SUBTREE_INDEX,
   321→    dataColumnSidecar.signedBlockHeader.message.bodyRoot
   322→  );
   323→}
   324→
   325→/**
   326→ * SPEC FUNCTION
   327→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#compute_subnet_for_data_column_sidecar
   328→ */
   329→export function computeSubnetForDataColumnSidecar(
   330→  config: ChainConfig,
   331→  columnSidecar: fulu.DataColumnSidecar
   332→): SubnetID {
   333→  return columnSidecar.index % config.DATA_COLUMN_SIDECAR_SUBNET_COUNT;
   334→}
