    23→  fork: ForkName
    24→): Promise<void> {
    25→  const block = signedBlock.message;
    26→  const blockSlot = block.slot;
    27→
    28→  // [IGNORE] The block is not from a future slot (with a MAXIMUM_GOSSIP_CLOCK_DISPARITY allowance) -- i.e.validate
    29→  // that signed_beacon_block.message.slot <= current_slot (a client MAY queue future blocks for processing at the
    30→  // appropriate slot).
    31→  const currentSlotWithGossipDisparity = chain.clock.currentSlotWithGossipDisparity;
    32→  if (currentSlotWithGossipDisparity < blockSlot) {
    33→    throw new BlockGossipError(GossipAction.IGNORE, {
    34→      code: BlockErrorCode.FUTURE_SLOT,
    35→      currentSlot: currentSlotWithGossipDisparity,
    36→      blockSlot,
    37→    });
    38→  }
    39→
    40→  // [IGNORE] The block is from a slot greater than the latest finalized slot -- i.e. validate that
    41→  // signed_beacon_block.message.slot > compute_start_slot_at_epoch(state.finalized_checkpoint.epoch)
    42→  const finalizedCheckpoint = chain.forkChoice.getFinalizedCheckpoint();
    43→  const finalizedSlot = computeStartSlotAtEpoch(finalizedCheckpoint.epoch);
    44→  if (blockSlot <= finalizedSlot) {
    45→    throw new BlockGossipError(GossipAction.IGNORE, {
    46→      code: BlockErrorCode.WOULD_REVERT_FINALIZED_SLOT,
    47→      blockSlot,
    48→      finalizedSlot,
    49→    });
    50→  }
    51→
    52→  // Check if the block is already known. We know it is post-finalization, so it is sufficient to check the fork choice.
    53→  //
    54→  // In normal operation this isn't necessary, however it is useful immediately after a
    55→  // reboot if the `observed_block_producers` cache is empty. In that case, without this
    56→  // check, we will load the parent and state from disk only to find out later that we
    57→  // already know this block.
    58→  const blockRoot = toRootHex(config.getForkTypes(blockSlot).BeaconBlock.hashTreeRoot(block));
    59→  if (chain.forkChoice.getBlockHex(blockRoot) !== null) {
    60→    throw new BlockGossipError(GossipAction.IGNORE, {code: BlockErrorCode.ALREADY_KNOWN, root: blockRoot});
    61→  }
    62→
    63→  // No need to check for badBlock
    64→  // Gossip de-duplicates messages so we shouldn't be able to receive a bad block twice
