    42→  let reject!: (e: Error) => void;
    43→  const promise = new Promise<T>((_resolve, _reject) => {
    44→    resolve = _resolve;
    45→    reject = _reject;
    46→  });
    47→  return {
    48→    promise,
    49→    resolve,
    50→    reject,
    51→  };
    52→}
    53→
    54→type BlockInputState<F extends ForkName> =
    55→  | {
    56→      hasBlock: false;
    57→      hasAllData: false;
    58→    }
    59→  | {
    60→      hasBlock: false;
    61→      hasAllData: true;
    62→    }
    63→  | {
    64→      hasBlock: true;
    65→      hasAllData: false;
    66→      block: SignedBeaconBlock<F>;
    67→      source: SourceMeta;
    68→    }
    69→  | {
    70→      hasBlock: true;
    71→      hasAllData: true;
    72→      block: SignedBeaconBlock<F>;
    73→      source: SourceMeta;
    74→      timeCompleteSec: number;
    75→    };
    76→
    77→abstract class AbstractBlockInput<F extends ForkName = ForkName, TData extends DAData = DAData>
    78→  implements IBlockInput<F, TData>
    79→{
    80→  abstract type: DAType;
    81→  daOutOfRange: boolean;
    82→  timeCreatedSec: number;
    83→
    84→  forkName: ForkName;
    85→  slot: Slot;
    86→  blockRootHex: string;
    87→  parentRootHex: string;
    88→
    89→  abstract state: BlockInputState<F>;
    90→
    91→  protected blockPromise = createPromise<SignedBeaconBlock<F>>();
    92→  protected dataPromise = createPromise<TData>();
    93→
    94→  constructor(init: BlockInputInit) {
    95→    this.daOutOfRange = init.daOutOfRange;
    96→    this.timeCreatedSec = init.timeCreated;
    97→    this.forkName = init.forkName;
    98→    this.slot = init.slot;
    99→    this.blockRootHex = init.blockRootHex;
   100→    this.parentRootHex = init.parentRootHex;
   101→  }
   102→
   103→  abstract addBlock(props: AddBlock<F>): void;
   104→
   105→  hasBlock(): boolean {
   106→    return this.state.hasBlock;
   107→  }
   108→
   109→  getBlock(): SignedBeaconBlock<F> {
   110→    if (!this.state.hasBlock) {
   111→      throw new BlockInputError(
   112→        {
   113→          code: BlockInputErrorCode.MISSING_BLOCK,
   114→          blockRoot: this.blockRootHex,
   115→        },
   116→        "Cannot getBlock from BlockInput without a block"
   117→      );
   118→    }
   119→    return this.state.block;
   120→  }
   121→
   122→  getBlockSource(): SourceMeta {
   123→    if (!this.state.hasBlock) {
   124→      throw new BlockInputError(
   125→        {
   126→          code: BlockInputErrorCode.MISSING_BLOCK,
   127→          blockRoot: this.blockRootHex,
   128→        },
   129→        "Cannot getBlockSource from BlockInput without a block"
   130→      );
   131→    }
   132→    return this.state.source;
   133→  }
   134→
   135→  hasAllData(): boolean {
   136→    return this.state.hasAllData;
   137→  }
   138→
   139→  hasBlockAndAllData(): boolean {
   140→    return this.state.hasBlock && this.state.hasAllData;
   141→  }
   142→
   143→  getLogMeta(): LogMetaBasic {
   144→    return {
   145→      blockRoot: prettyBytes(this.blockRootHex),
   146→      slot: this.slot,
   147→      timeCreatedSec: this.timeCreatedSec,
   148→    };
   149→  }
   150→
   151→  getTimeComplete(): number {
   152→    if (!this.state.hasBlock || !this.state.hasAllData) {
   153→      throw new BlockInputError(
   154→        {
   155→          code: BlockInputErrorCode.MISSING_TIME_COMPLETE,
   156→          blockRoot: this.blockRootHex,
   157→        },
   158→        "Cannot getTimeComplete from BlockInput without a block and data"
   159→      );
   160→    }
   161→    return this.state.timeCompleteSec;
   162→  }
   163→
   164→  waitForBlock(timeout: number, signal?: AbortSignal): Promise<SignedBeaconBlock<F>> {
   165→    if (!this.state.hasBlock) {
   166→      return withTimeout(() => this.blockPromise.promise, timeout, signal);
   167→    }
   168→    return Promise.resolve(this.state.block);
   169→  }
   170→  waitForAllData(timeout: number, signal?: AbortSignal): Promise<TData> {
   171→    return withTimeout(() => this.dataPromise.promise, timeout, signal);
   172→  }
   173→
   174→  async waitForBlockAndAllData(timeout: number, signal?: AbortSignal): Promise<this> {
   175→    if (!this.state.hasBlock || !this.state.hasAllData) {
   176→      await withTimeout(() => Promise.all([this.blockPromise.promise, this.dataPromise.promise]), timeout, signal);
   177→    }
   178→    return this;
   179→  }
   180→}
   181→
   182→// Pre-DA
   183→
   184→type BlockInputPreDataState = {
   185→  hasBlock: true;
   186→  hasAllData: true;
   187→  block: SignedBeaconBlock<ForkPreDeneb>;
   188→  source: SourceMeta;
   189→  timeCompleteSec: number;
   190→};
   191→
   192→/**
   193→ * Pre-DA, BlockInput only has a single state.
   194→ * - the block simply exists
   195→ */
   196→export class BlockInputPreData extends AbstractBlockInput<ForkPreDeneb, null> {
   197→  type = DAType.PreData as const;
   198→
   199→  state: BlockInputPreDataState;
   200→
   201→  private constructor(init: BlockInputInit, state: BlockInputPreDataState) {
   202→    super(init);
   203→    this.state = state;
   204→  }
   205→
   206→  static createFromBlock(props: AddBlock & CreateBlockInputMeta): BlockInputPreData {
   207→    const init: BlockInputInit = {
   208→      daOutOfRange: props.daOutOfRange,
   209→      timeCreated: props.source.seenTimestampSec,
   210→      forkName: props.forkName,
   211→      slot: props.block.message.slot,
   212→      blockRootHex: props.blockRootHex,
   213→      parentRootHex: toRootHex(props.block.message.parentRoot),
   214→    };
   215→    const state: BlockInputPreDataState = {
   216→      hasBlock: true,
   217→      hasAllData: true,
   218→      block: props.block,
   219→      source: props.source,
   220→      timeCompleteSec: props.source.seenTimestampSec,
   221→    };
   222→    return new BlockInputPreData(init, state);
   223→  }
   224→
   225→  addBlock(_: AddBlock): void {
   226→    throw new BlockInputError(
   227→      {
   228→        code: BlockInputErrorCode.INVALID_CONSTRUCTION,
   229→        blockRoot: this.blockRootHex,
   230→      },
   231→      "Cannot addBlock to BlockInputPreData"
   232→    );
   233→  }
   234→}
   235→
   236→// Blobs DA
   237→
   238→export type ForkBlobsDA = ForkName.deneb | ForkName.electra;
   239→
   240→type BlockInputBlobsState =
   241→  | {
   242→      hasBlock: true;
   243→      hasAllData: true;
   244→      versionedHashes: VersionedHashes;
   245→      block: SignedBeaconBlock<ForkBlobsDA>;
   246→      source: SourceMeta;
   247→      timeCompleteSec: number;
   248→    }
   249→  | {
   250→      hasBlock: true;
   251→      hasAllData: false;
   252→      versionedHashes: VersionedHashes;
   253→      block: SignedBeaconBlock<ForkBlobsDA>;
   254→      source: SourceMeta;
   255→    }
   256→  | {
   257→      hasBlock: false;
   258→      hasAllData: false;
   259→    };
   260→
   261→/**
   262→ * With blobs, BlockInput has several states:
   263→ * - The block is seen and all blobs are seen
   264→ * - The block is seen and all blobs are not yet seen
   265→ * - The block is yet not seen and its unknown if all blobs are seen
   266→ */
   267→export class BlockInputBlobs extends AbstractBlockInput<ForkBlobsDA, deneb.BlobSidecars> {
   268→  type = DAType.Blobs as const;
   269→
   270→  state: BlockInputBlobsState;
   271→  private blobsCache = new Map<BlobIndex, BlobWithSource>();
   272→
   273→  private constructor(init: BlockInputInit, state: BlockInputBlobsState) {
   274→    super(init);
   275→    this.state = state;
   276→  }
   277→
   278→  static createFromBlock(props: AddBlock<ForkBlobsDA> & CreateBlockInputMeta): BlockInputBlobs {
   279→    const hasAllData = props.daOutOfRange || props.block.message.body.blobKzgCommitments.length === 0;
   280→
   281→    const state = {
   282→      hasBlock: true,
   283→      hasAllData,
   284→      versionedHashes: props.block.message.body.blobKzgCommitments.map(kzgCommitmentToVersionedHash),
   285→      block: props.block,
   286→      source: props.source,
   287→      timeCompleteSec: hasAllData ? props.source.seenTimestampSec : undefined,
   288→    } as BlockInputBlobsState;
   289→    const init: BlockInputInit = {
   290→      daOutOfRange: props.daOutOfRange,
   291→      timeCreated: props.source.seenTimestampSec,
   292→      forkName: props.forkName,
   293→      slot: props.block.message.slot,
   294→      blockRootHex: props.blockRootHex,
   295→      parentRootHex: toRootHex(props.block.message.parentRoot),
   296→    };
   297→    const blockInput = new BlockInputBlobs(init, state);
   298→    blockInput.blockPromise.resolve(props.block);
   299→    if (hasAllData) {
   300→      blockInput.dataPromise.resolve([]);
   301→    }
   302→    return blockInput;
   303→  }
   304→
   305→  static createFromBlob(props: AddBlob & CreateBlockInputMeta): BlockInputBlobs {
   306→    const state: BlockInputBlobsState = {
   307→      hasBlock: false,
   308→      hasAllData: false,
   309→    };
   310→    const init: BlockInputInit = {
   311→      daOutOfRange: props.daOutOfRange,
   312→      timeCreated: props.seenTimestampSec,
   313→      forkName: props.forkName,
   314→      blockRootHex: props.blockRootHex,
   315→      parentRootHex: toRootHex(props.blobSidecar.signedBlockHeader.message.parentRoot),
   316→      slot: props.blobSidecar.signedBlockHeader.message.slot,
   317→    };
   318→    const blockInput = new BlockInputBlobs(init, state);
   319→    blockInput.blobsCache.set(props.blobSidecar.index, {
   320→      blobSidecar: props.blobSidecar,
   321→      source: props.source,
   322→      seenTimestampSec: props.seenTimestampSec,
   323→      peerIdStr: props.peerIdStr,
   324→    });
   325→    return blockInput;
   326→  }
   327→
   328→  getLogMeta(): LogMetaBlobs {
   329→    return {
   330→      blockRoot: prettyBytes(this.blockRootHex),
   331→      slot: this.slot,
   332→      timeCreatedSec: this.timeCreatedSec,
   333→      expectedBlobs: this.state.hasBlock ? this.state.block.message.body.blobKzgCommitments.length : "unknown",
   334→      receivedBlobs: this.blobsCache.size,
   335→    };
   336→  }
   337→
   338→  addBlock({blockRootHex, block, source}: AddBlock<ForkBlobsDA>): void {
   339→    if (this.state.hasBlock) {
   340→      throw new BlockInputError(
   341→        {
   342→          code: BlockInputErrorCode.INVALID_CONSTRUCTION,
   343→          blockRoot: this.blockRootHex,
   344→        },
   345→        "Cannot addBlock to BlockInputBlobs after it already has a block"
   346→      );
   347→    }
   348→
   349→    // this check suffices for checking slot, parentRoot, and forkName
   350→    if (blockRootHex !== this.blockRootHex) {
   351→      throw new BlockInputError(
   352→        {
   353→          code: BlockInputErrorCode.MISMATCHED_ROOT_HEX,
   354→          blockInputRoot: this.blockRootHex,
   355→          mismatchedRoot: blockRootHex,
   356→          source: source.source,
   357→          peerId: `${source.peerIdStr}`,
   358→        },
   359→        "addBlock blockRootHex does not match BlockInput.blockRootHex"
   360→      );
   361→    }
   362→
   363→    for (const {blobSidecar} of this.blobsCache.values()) {
   364→      if (!blockAndBlobArePaired(block, blobSidecar)) {
   365→        this.blobsCache.delete(blobSidecar.index);
   366→        // TODO: (@matthewkeil) spec says to ignore invalid blobs but should we downscore the peer maybe?
   367→        // this.logger?.error(`Removing blobIndex=${blobSidecar.index} from BlockInput`, {}, err);
   368→      }
   369→    }
   370→
   371→    const hasAllData = this.blobsCache.size === block.message.body.blobKzgCommitments.length;
   372→
   373→    this.state = {
   374→      ...this.state,
   375→      hasBlock: true,
   376→      hasAllData,
   377→      block,
   378→      versionedHashes: block.message.body.blobKzgCommitments.map(kzgCommitmentToVersionedHash),
   379→      source,
   380→      timeCompleteSec: hasAllData ? source.seenTimestampSec : undefined,
   381→    } as BlockInputBlobsState;
   382→    this.blockPromise.resolve(block);
   383→    if (hasAllData) {
   384→      this.dataPromise.resolve(this.getBlobs());
   385→    }
   386→  }
   387→
   388→  hasBlob(blobIndex: BlobIndex): boolean {
   389→    return this.blobsCache.has(blobIndex);
   390→  }
   391→
   392→  addBlob({blockRootHex, blobSidecar, source, peerIdStr, seenTimestampSec}: AddBlob): void {
   393→    if (this.state.hasAllData) {
   394→      throw new BlockInputError(
   395→        {
   396→          code: BlockInputErrorCode.INVALID_CONSTRUCTION,
   397→          blockRoot: this.blockRootHex,
   398→        },
   399→        "Cannot addBlob to BlockInputBlobs after it already is complete"
   400→      );
   401→    }
   402→    if (this.blobsCache.has(blobSidecar.index)) {
   403→      throw new BlockInputError(
   404→        {
   405→          code: BlockInputErrorCode.INVALID_CONSTRUCTION,
   406→          blockRoot: this.blockRootHex,
   407→        },
   408→        "Cannot addBlob to BlockInputBlobs with duplicate blobIndex"
   409→      );
   410→    }
   411→
   412→    // this check suffices for checking slot, parentRoot, and forkName
   413→    if (blockRootHex !== this.blockRootHex) {
   414→      throw new BlockInputError(
   415→        {
   416→          code: BlockInputErrorCode.MISMATCHED_ROOT_HEX,
   417→          blockInputRoot: this.blockRootHex,
   418→          mismatchedRoot: blockRootHex,
   419→          source: source,
   420→          peerId: `${peerIdStr}`,
   421→        },
   422→        "Blob BeaconBlockHeader blockRootHex does not match BlockInput.blockRootHex"
   423→      );
   424→    }
   425→
   426→    if (this.state.hasBlock) {
   427→      assertBlockAndBlobArePaired(this.blockRootHex, this.state.block, blobSidecar);
   428→    }
   429→
   430→    this.blobsCache.set(blobSidecar.index, {blobSidecar, source, seenTimestampSec, peerIdStr});
   431→
   432→    if (this.state.hasBlock && this.blobsCache.size === this.state.block.message.body.blobKzgCommitments.length) {
   433→      this.state = {
   434→        ...this.state,
   435→        hasAllData: true,
   436→        timeCompleteSec: seenTimestampSec,
   437→      };
   438→      this.dataPromise.resolve([...this.blobsCache.values()].map(({blobSidecar}) => blobSidecar));
   439→    }
   440→  }
   441→
   442→  getVersionedHashes(): VersionedHashes {
   443→    if (!this.state.hasBlock) {
   444→      throw new BlockInputError(
   445→        {
   446→          code: BlockInputErrorCode.INCOMPLETE_DATA,
   447→          ...this.getLogMeta(),
   448→        },
   449→        "Cannot get versioned hashes. Block is unknown"
   450→      );
   451→    }
   452→    return this.state.versionedHashes;
   453→  }
   454→
   455→  getMissingBlobMeta(): BlobMeta[] {
   456→    if (!this.state.hasBlock) {
   457→      throw new BlockInputError(
   458→        {
   459→          code: BlockInputErrorCode.INCOMPLETE_DATA,
   460→          ...this.getLogMeta(),
   461→        },
   462→        "Cannot get missing blobs. Block is unknown"
   463→      );
   464→    }
   465→    if (this.state.hasAllData) {
   466→      return [];
   467→    }
   468→
   469→    const blobMeta: BlobMeta[] = [];
   470→    const versionedHashes = this.state.versionedHashes;
   471→    for (let index = 0; index < versionedHashes.length; index++) {
   472→      if (!this.blobsCache.has(index)) {
   473→        blobMeta.push({
   474→          index,
   475→          blockRoot: fromHex(this.blockRootHex),
   476→          versionHash: versionedHashes[index],
   477→        });
   478→      }
   479→    }
   480→    return blobMeta;
   481→  }
   482→
   483→  getAllBlobsWithSource(): BlobWithSource[] {
   484→    if (!this.state.hasAllData) {
   485→      throw new BlockInputError(
   486→        {
   487→          code: BlockInputErrorCode.INCOMPLETE_DATA,
   488→          ...this.getLogMeta(),
   489→        },
   490→        "Cannot get all blobs. DA status is not complete"
   491→      );
   492→    }
   493→    return [...this.blobsCache.values()];
   494→  }
   495→
   496→  getBlobs(): deneb.BlobSidecars {
   497→    return this.getAllBlobsWithSource().map(({blobSidecar}) => blobSidecar);
   498→  }
   499→}
   500→
   501→function blockAndBlobArePaired(block: SignedBeaconBlock<ForkBlobsDA>, blobSidecar: deneb.BlobSidecar): boolean {
   502→  const blockCommitment = block.message.body.blobKzgCommitments[blobSidecar.index];
   503→  if (!blockCommitment || !blobSidecar.kzgCommitment) {
   504→    return false;
   505→  }
   506→  return Buffer.compare(blockCommitment, blobSidecar.kzgCommitment) === 0;
   507→}
   508→
   509→function assertBlockAndBlobArePaired(
   510→  blockRootHex: string,
   511→  block: SignedBeaconBlock<ForkBlobsDA>,
   512→  blobSidecar: deneb.BlobSidecar
   513→): void {
   514→  if (!blockAndBlobArePaired(block, blobSidecar)) {
   515→    // TODO: (@matthewkeil) should this eject the bad blob instead? No way to tell if the blob or the block
   516→    //       has the invalid commitment. Guessing it would be the blob though because we match via block
   517→    //       hashTreeRoot and we do not take a hashTreeRoot of the BlobSidecar
   518→    throw new BlockInputError(
   519→      {
   520→        code: BlockInputErrorCode.MISMATCHED_KZG_COMMITMENT,
   521→        blockRoot: blockRootHex,
   522→        slot: block.message.slot,
   523→        sidecarIndex: blobSidecar.index,
   524→      },
   525→      "BlobSidecar commitment does not match block commitment"
   526→    );
   527→  }
   528→}
   529→
   530→// Columns DA
   531→
   532→export type ForkColumnsDA = ForkName.fulu;
   533→
   534→type BlockInputColumnsState =
   535→  | {
   536→      hasBlock: true;
   537→      hasAllData: true;
   538→      versionedHashes: VersionedHashes;
   539→      block: SignedBeaconBlock<ForkColumnsDA>;
   540→      source: SourceMeta;
   541→      timeCompleteSec: number;
   542→    }
   543→  | {
   544→      hasBlock: true;
   545→      hasAllData: false;
   546→      versionedHashes: VersionedHashes;
   547→      block: SignedBeaconBlock<ForkColumnsDA>;
   548→      source: SourceMeta;
   549→    }
   550→  | {
   551→      hasBlock: false;
   552→      hasAllData: true;
   553→      versionedHashes: VersionedHashes;
   554→    }
   555→  | {
   556→      hasBlock: false;
   557→      hasAllData: false;
   558→      versionedHashes: VersionedHashes;
   559→    };
   560→/**
   561→ * With columns, BlockInput has several states:
   562→ * - The block is seen and all required sampled columns are seen
   563→ * - The block is seen and all required sampled columns are not yet seen
   564→ * - The block is not yet seen and all required sampled columns are seen
   565→ * - The block is not yet seen and all required sampled columns are not yet seen
   566→ */
   567→export class BlockInputColumns extends AbstractBlockInput<ForkColumnsDA, fulu.DataColumnSidecars> {
   568→  type = DAType.Columns as const;
   569→
   570→  state: BlockInputColumnsState;
   571→
   572→  private columnsCache = new Map<ColumnIndex, ColumnWithSource>();
   573→  private readonly sampledColumns: ColumnIndex[];
   574→  private readonly custodyColumns: ColumnIndex[];
   575→
   576→  private constructor(
   577→    init: BlockInputInit,
   578→    state: BlockInputColumnsState,
   579→    sampledColumns: ColumnIndex[],
   580→    custodyColumns: ColumnIndex[]
   581→  ) {
   582→    super(init);
   583→    this.state = state;
   584→    this.sampledColumns = sampledColumns;
   585→    this.custodyColumns = custodyColumns;
   586→  }
   587→
   588→  static createFromBlock(
   589→    props: AddBlock<ForkColumnsDA> &
   590→      CreateBlockInputMeta & {sampledColumns: ColumnIndex[]; custodyColumns: ColumnIndex[]}
   591→  ): BlockInputColumns {
   592→    const hasAllData =
   593→      props.daOutOfRange ||
   594→      props.block.message.body.blobKzgCommitments.length === 0 ||
   595→      props.sampledColumns.length === 0;
   596→    const state = {
   597→      hasBlock: true,
   598→      hasAllData,
   599→      versionedHashes: props.block.message.body.blobKzgCommitments.map(kzgCommitmentToVersionedHash),
   600→      block: props.block,
   601→      source: props.source,
   602→      timeCreated: props.source.seenTimestampSec,
   603→      timeCompleteSec: hasAllData ? props.source.seenTimestampSec : undefined,
   604→    } as BlockInputColumnsState;
   605→    const init: BlockInputInit = {
   606→      daOutOfRange: props.daOutOfRange,
   607→      timeCreated: props.source.seenTimestampSec,
   608→      forkName: props.forkName,
   609→      blockRootHex: props.blockRootHex,
   610→      parentRootHex: toRootHex(props.block.message.parentRoot),
   611→      slot: props.block.message.slot,
   612→    };
   613→    const blockInput = new BlockInputColumns(init, state, props.sampledColumns, props.custodyColumns);
   614→
   615→    blockInput.blockPromise.resolve(props.block);
   616→    if (hasAllData) {
   617→      blockInput.dataPromise.resolve([]);
   618→    }
   619→    return blockInput;
   620→  }
   621→
   622→  static createFromColumn(
   623→    props: AddColumn & CreateBlockInputMeta & {sampledColumns: ColumnIndex[]; custodyColumns: ColumnIndex[]}
   624→  ): BlockInputColumns {
   625→    const hasAllData = props.sampledColumns.length === 0;
   626→    const state: BlockInputColumnsState = {
   627→      hasBlock: false,
   628→      hasAllData,
   629→      versionedHashes: props.columnSidecar.kzgCommitments.map(kzgCommitmentToVersionedHash),
   630→    };
   631→    const init: BlockInputInit = {
   632→      daOutOfRange: false,
   633→      timeCreated: props.seenTimestampSec,
   634→      forkName: props.forkName,
   635→      blockRootHex: props.blockRootHex,
   636→      parentRootHex: toRootHex(props.columnSidecar.signedBlockHeader.message.parentRoot),
   637→      slot: props.columnSidecar.signedBlockHeader.message.slot,
   638→    };
   639→    const blockInput = new BlockInputColumns(init, state, props.sampledColumns, props.custodyColumns);
   640→    if (hasAllData) {
   641→      blockInput.dataPromise.resolve([]);
   642→    }
   643→    return blockInput;
   644→  }
   645→
   646→  getLogMeta(): LogMetaColumns {
   647→    return {
   648→      blockRoot: prettyBytes(this.blockRootHex),
   649→      slot: this.slot,
   650→      timeCreatedSec: this.timeCreatedSec,
   651→      expectedColumns:
