   301→    valid = await kzg.asyncVerifyCellKzgProofBatch(commitments, cellIndices, cells, proofs);
   302→  } catch (e) {
   303→    (e as Error).message = `Error on asyncVerifyCellKzgProofBatch: ${(e as Error).message}`;
