    25→export async function verifyBlocksStateTransitionOnly(
    26→  preState0: CachedBeaconStateAllForks,
    27→  blocks: BlockInput[],
    28→  dataAvailabilityStatuses: DataAvailabilityStatus[],
    29→  logger: Logger,
    30→  metrics: Metrics | null,
    31→  validatorMonitor: ValidatorMonitor | null,
    32→  signal: AbortSignal,
    33→  opts: BlockProcessOpts & ImportBlockOpts
    34→): Promise<{postStates: CachedBeaconStateAllForks[]; proposerBalanceDeltas: number[]; verifyStateTime: number}> {
    35→  const postStates: CachedBeaconStateAllForks[] = [];
    36→  const proposerBalanceDeltas: number[] = [];
    37→  const recvToValLatency = Date.now() / 1000 - (opts.seenTimestampSec ?? Date.now() / 1000);
    38→
    39→  for (let i = 0; i < blocks.length; i++) {
    40→    const {validProposerSignature, validSignatures} = opts;
    41→    const {block} = blocks[i];
    42→    const preState = i === 0 ? preState0 : postStates[i - 1];
    43→    const dataAvailabilityStatus = dataAvailabilityStatuses[i];
    44→
    45→    // STFN - per_slot_processing() + per_block_processing()
